window.PARAGRAPH6_EXPANDED_QUESTIONS = [{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(1) Apartmanın köhneleşmiş basamaklarını çifter çifter çıktı. (2) Eve girip kimseyi bulamayınca karısının komşuda, çocukların ise sokakta olabileceğini düşündü. (3) İçerisi avazı çıktığı kadar bağıran yoğurtçuların, şıracıların sesiyle doldu. (4) Sokağa bakmak için pencereyi açtığında güneşin ufukta nazlanarak batmaya başladığını gördü.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde kişileştirmeye yer verilmiştir?","options":["1","2","3","4"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(1) Çocukluk yıllarımda birçok arkadaşım kitaba ulaşmakta bir hayli güçlük çekerdi. (2) Oysa, o yaşlarda kitaba erişmek benim için çok kolaydı çünkü hem dedem hem de amcam kucak dolusu masalla bize gelirdi. (3) Amcam Fransız masallarını okumamı isterdi, dedemse Türk klasiklerini okumam için ısrar ederdi. (4) Ben Türk klasiklerini sevdiğimden en çok onları okumayı tercih ederdim.","stem":"Bu metindeki numaralanmış cümlelerin hangilerinde neden-sonuç ilişkisi vardır?","options":["1 ve 3","1 ve 4","2 ve 3","2 ve 4"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Çıkarım yapma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Uzun yıllardır robot geliştirme projeleri yürüten İtalya, İsviçre ve Almanya’dan bir grup bilim insanının 2014 yılında geliştirdikleri dokunma hissine sahip biyonik el, çok büyük bilgisayarlar yardımıyla çalışıyordu.","stem":"Bu metinden aşağıdakilerin hangisine kesinlikle ulaşılır?","options":["Robot geliştirme çalışmalarının uzun zamandır sürdürüldüğüne","Dokunma hissine sahip ilk biyonik elin 2014 yılında tasarlandığına","İtalya, İsviçre ve Almanya’nın robot geliştirme çalışmalarına öncülük ettiğine","Robot geliştirme çalışmalarının sadece çok büyük bilgisayarlarla gerçekleşebildiğine"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(1) Deniz gergedanları, doğduklarında koyu mavi ve gri renkte olurlar. (2) Yetişkin olduklarındaysa renkleri beyaza döner ve benekleri ortaya çıkar. (3) Yetişkin bir gergedanın çenesinde uzunluğu üç metreye kadar ulaşan köpek dişi bulunur. (4) Boynuzu andıran bu diş onlara ilginç bir görünüm kazandırır.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde kişisel bir görüşe yer verilmiştir?","options":["1","2","3","4"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Karıncalar birçok odadan oluşan yuvalarını yer altına tüneller şeklinde yapar. Karınca yuvasındaki her bir odanın farklı işlevi vardır. Bazı odalarda yavru karıncalar büyütülürken bazılarında besinler depolanır. Her yuvada işçi karıncalar ve bir de kraliçe karınca yaşar. Yuvanın en büyük karıncası olan kraliçe karınca yavruların beslenmesi ve büyütülmesinden sorumludur. İşçi karıncalar ise yuvayı temizlemek, korumak ve yuvaya besin getirmek gibi görevler üstlenir.","stem":"Bu metinde ‘‘karıncalar’’ ile ilgili aşağıdakilerden hangisine değinilmemiştir?","options":["Yuvadaki odaları çeşitli amaçlar için kullandıklarına","Kraliçe karıncanın yuvayı koruduğuna","Yuvalarını yerin altına yaptıklarına","İşçi karıncaların farklı işlerden sorumlu olduğuna"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Kangurular, Avustralya kıtasının ulusal sembolüdür. Bu hayvanların figürlerine Avustralya’daki paraların üzerinde, posta pullarında, uçaklarda ve daha pek çok yerde rastlamak mümkün. Memeliler familyasından olan kanguruların altmıştan fazla türü vardır. Dört ayaklı hayvanlar olsalar da biz onları genellikle arka ayakları üzerinde dururken görürüz. Çünkü ön ayakları kısa olan kangurular, uzun ve güçlü olan arka ayaklarını zıplamak ve koşmak için daha fazla kullanır. Kanguruların arka ayakları öyle güçlüdür ki bir kanguru boyunun üç katı kadar ileriye zıplayabilir ve çok hızlı koşabilir.","stem":"Buna göre, kangurularla ilgili; 1. boylarının zıplamalarında etkili olduğu, 2. farklı kıtalarda da bulunduğu, 3. figürünün kıtanın simgesi olarak çeşitli alanlarda kullanıldığı, 4. arka ayaklarının öndekilerden farklı özellikler taşıdığı ifadelerinden hangileri söylenebilir?","options":["1 - 2","1 - 4","2 - 3","3 - 4"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(1) Mevsiminde tezgâhlardan alınan sebze ve meyveler daha sonra yenmek için çeşitli yöntemlerle saklanabilir. (2) Bu yöntemlerin başlıcaları kurutma, dondurma, tuzlama ve vakumlamadır. (3) Bu saklama yöntemlerinden sebze ve meyvelere en uygun olanı tercih edilirse onların besin değerleri korunmuş olur. (4) Böylelikle üretildikleri mevsimin dışında da bu yiyecekler gönül rahatlığıyla tüketilebilir.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde amaç-sonuç ilişkisi vardır?","options":["1","2","3","4"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Kendinizi iyi hissetmek istiyorsanız bol bol temiz hava alıp yürüyüş yapın. Bakımlı olmaya ve sağlıklı beslenmeye özen gösterin, fırsat buldukça yeni yerler keşfedin. Ayrıca düşünme biçiminizin de iyi hissetmenizi doğrudan etkilediğini unutmayın. Bu yüzden - - - -. Çünkü olumsuz düşünürseniz sadece olumsuzlukları görürsünüz ve kendinizi kötü hissedersiniz.","stem":"Bu metinde boş bırakılan yere düşüncenin akışına göre aşağıdakilerden hangisi getirilmelidir?","options":["spor yapın ve uyku düzeninize dikkat edin","olumlu düşünmeyi hayat tarzı hâline getirin","olumsuzlukların hayatın gerçeği olduğunu bilin","yaşadığınız çevreyi değiştirmeye çalışın"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Konu bulma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Caz müziği yapan müzisyenler, nefesli çalgıları üflerken nefes çevirme olarak adlandırılan bir teknik uygular. Bu teknikte ağızda biriktirdikleri havayı çalgıya üflerken burundan nefes almaya devam ederler. Böylece çalınan melodiler, müzisyen nefes alırken kesintiye uğramamış olur. Amerikalı caz sanatçısı Louis Armstrong bu tekniği kullanmadaki ustalığıyla bilinir.","stem":"Bu metnin konusu aşağıdakilerden hangisidir?","options":["Caz müziğinin doğduğu yer","Caz müziğinde çalınan melodiler","Caz müziğinde kullanılan çalgılar","Caz müziğinde uygulanan nefes tekniği"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Tüm meyvelerde doğal olarak bulunan pektin maddesi, meyveden yapılan reçelin kıvam almasını sağlar. Her meyveden reçel yapılabilir ama fazla pektin içeren elma, erik, üzüm ve ayva gibi meyveler reçel yapımına daha uygundur. Bunun yanında reçeli yapılacak meyvenin fazla olgunlaşmamış olmasına da dikkat edilmelidir. Çünkü meyve olgunlaştıkça içerisindeki pektin miktarı azalır ve reçelin o bildiğimiz koyu kıvamı alması güçleşir.","stem":"Bu metinde aşağıdakilerden hangisine değinilmemiştir?","options":["Bazı meyvelerin reçel yapımına daha elverişli olduğuna","Pektin oranının her meyvede aynı olduğuna","Meyvelerde pektin maddesinin kendiliğinden bulunduğuna","Olgunlaşmanın reçelin kıvam almasındaki etkisine"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Ölüdeniz Uluslararası Hava Oyunları Festivali, ekim ayında Fethiye’de düzenlendi. Festival her sene olduğu gibi bu sene de Babadağ’ın zirvesinde başladı. Gökyüzü dalışı, yarasa adam uçuşu, kanatlı uçuşlar gibi birçok gösterinin yapıldığı festivalde hem ülkemizden hem de diğer ülkelerden pek çok sporcu yer aldı. Babadağ’dan peş peşe havalanan rengârenk yamaç paraşütleri izleyicilerde coşku ve hayranlık uyandırdı.","stem":"Bu metinden ‘‘Ölüdeniz Uluslararası Hava Oyunları Festivali’’ ile ilgili aşağıdakilerden hangisine ulaşılamaz?","options":["Yurt dışından katılımın olduğuna","Uçuş gösterilerinin yapıldığına","Başlangıç yerinin her sene değiştiğine","Daha önceki yıllarda da düzenlendiğine"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(1) Afyonkarahisar’ın Sinanpaşa ilçesine bağlı Düzağaç köyünde, köylülerin ve yoldan gelip geçenlerin uğradığı bir pınar vardır. (2) Bu pınar Anadolu’nun Türkleşmesi sırasında Erenler Pınarı adını almıştır. (3) Yunan işgali boyunca suyunu düşman askerinden gizleyen pınar, Büyük Taarruz başlayınca coşmuş, ayna gibi olmuş ve yöreye gelen Türk askerlerine yeniden kucak açmıştır. (4) Savaş yılları geçtikten sonra köy halkı pınarın üzerine değirmenler kurmuş ve bu değirmenler uzun yıllar kullanılmıştır.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde kişisel bir görüşe yer verilmiştir?","options":["1","2","3","4"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(1) Kutup ışıkları, Dünya’nın yalnızca Kuzey ve Güney Kutbu’nda rastlanan bir doğa olayıdır. (2) Bu ışıklar Dünya’yı saran atmosferde mavi, sarı, kırmızı ve yeşil renklerde görünür. (3) Gökyüzünün çok yukarılarında meydana gelen bu ışıklar bazen geniş bir alana yayılır. (4) Pek çok ülkeden izlenebilen bu ışıkları, Türkiye, kutup bölgelerine uzak olduğu için bizim izleyebilmemiz mümkün değildir.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde neden-sonuç ilişkisi vardır?","options":["1","2","3","4"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Başlık bulma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Dünya üzerindeki tüm denizler farklı yaşam alanları barındırır. Okyanuslarda ve açık denizlerde dev balinalar, göçebe foklar, yırtıcı köpek balıkları yaşarken kıyılarda daha küçük balıklar ve mercan resifleri yaşamaktadır. Kıyıların daha sıcak kesimlerinde ise küçük deniz canlılarına ev sahipliği yapan, devasa deniz yosunlarından oluşan ormanlar bulunur. Çevre koşullarına bağlı olarak bu alanlar değiştiğinde, denizlerdeki birçok tür yeni yaşam alanlarına uyum sağlayarak var olmaya devam eder.","stem":"Bu metne getirebilecek en uygun başlık aşağıdakilerden hangisidir?","options":["Çevre kirliliğinin deniz üzerindeki etkisi","Deniz canlıların barınma yöntemleri","İklimin yaşam alanlarının değişmesindeki rolü","Deniz canlılarının yaşam alanları"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Rasim Bey, yeni aldığı tabloyu duvara asmak ister. Evde çivi bulur ama çekiç yoktur. Komşusuna gidip ondan çekiç istemeye karar verir. Ancak o anda şüpheye düşer. “Ya vermek istemezse? Zaten dün de beni soğuk bir selamla geçiştirdi. Belki bir acelesi vardı, belki de bilerek yaptı. Bilmiyorum. Birisi benden ödünç bir şey istese ben verirdim. O niye vermiyor? Üstüne üstlük sırf bir çekici var diye ona muhtacım sanıyor.” Öfkeyle kalkıp karşı daireye gider, kapıyı çalar. Komşusu güler yüzle kapıyı açar ama daha “Merhaba.” bile diyemeden Rasim Bey ona bağırır: Al çekicini, başına çal! Komşusu, onun bu davranışına anlam vermeye çalışırken Rasim Bey kendi dairesine döner ve kapıyı hızla çarpar.","stem":"Bu metnin ana düşüncesi aşağıdakilerden hangisidir?","options":["Kişiler hakkında yanlış ve yersiz düşüncelere kapılmak ilişkileri olumsuz etkiler.","Komşularıyla yardımlaşma içinde olanlar huzurlu bir yaşam sürer.","Kendisinden başkasını düşünmeyenler, hiçbir zaman kalıcı dostluklar kuramaz.","Başkasının iyiliğini istemeyenler hayatları boyunca mutlu olamaz."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(1) Haftalar önce geldiğim bu sessiz sakin yerde, uzun bir akşam gezisinden dönüyorum. (2) Biçilmiş tarlaların ortasında uzanan patikada yürürken karşı tepenin üstündeki taş bina dikkatimi çekiyor. (3) Yıkık duvarlı bir bahçenin ortasındaki bu yapının, harap bir kaleyi andıran görüntüsü beni etkiliyor. (4) Vaktin erken olduğunu düşünerek bu binayı daha yakından görme isteğiyle tepeye tırmanıyorum.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde benzetme vardır?","options":["1","2","3","4"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Çıkarım yapma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Avustralyalı araştırmacılar, Antarktika’nın çok soğuk ve su miktarı çok az olan bir bölgesinde yeni bir bakteri türü keşfetti. Bu bakterinin, olumsuz yaşam koşulları karşısında, şimdiye kadar bilinen tüm bakterilere göre daha dayanıklı olduğu söyleniyor. Hava dışında başka bir şeye ihtiyaç duymayan bakteri, bu özelliğiyle diğer tüm bakterilerden ayrılıyor. Bakterinin bu yönü başka gezegenlerde yaşam olma ihtimalini güçlendiriyor.","stem":"Bu metinden aşağıdakilerin hangisine kesinlikle ulaşılır?","options":["Avustralyalı bilim insanlarının sadece bakteriler üzerine çalışma yaptığına","Bazı bakterilerin farklı gezegenlerde yaşadığına","Kötü yaşam koşullarının bakterilerin yaşam süresini kısalttığına","Keşfedilen bakterinin bazı yönleriyle ilk olma özelliği taşıdığına"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Hikâye unsurları","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Defne ve arkadaşları, ellerindeki haritadan daha önce geçmedikleri sokakları takip ederek meydana ulaştılar. Böylelikle yeni yerler de öğrenmiş oldular. Haritayla gezmeyi çok seven Defne, arkadaşlarına heyecanla “Haritada gösterilen diğer sokakları kullanarak eve dönmeye ne dersiniz?” diye sordu. Hepsi bu fikri çok beğendi ve neşeyle yeni sokaklardan geçerek evlerine döndüler.","stem":"Bu metinde aşağıdaki hikâye unsurlarından hangisi yoktur?","options":["Kişi","Zaman","Olay","Mekân"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(1) Şiirin dili günlük konuşma diline göre daha coşkulu, kendine özgü nitelikleri olan, yaratıcı bir dildir. (2) Şiir hayallerle şekillendiği için onun okuyucusunu özgürleştiren bir tarafı var. (3) Her duyguyu kendi tarzında ifade etmek isteyen biri için şiir kusursuz bir tür. (4) Çünkü onunla bütün duyguları ustaca dile getirmek mümkün.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde karşılaştırma yapılmıştır?","options":["1","2","3","4"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Çıkarım yapma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Doğup büyüdüğü coğrafya etkiler insanın kişiliğini. İnsanın macerası biraz da yaşadığı yerin macerasıdır. İki şehrin, şehir ile kasabanın, köy ile mezranın kültürleri arasındaki fark; doğrudan yansır insanın benliğine. Hatta bir şehrin iki ayrı semtinde yaşayan insanlar bile farklı kişilikler kazanır birbirinden.","stem":"Bu metne göre, 1. Şehirlerin kendine has kültür özellikleri vardır. 2. İnsanın davranışları ve alışkanlıkları ait olduğu kültüre göre şekillenir. 3. Yerleşim yerlerinin sınırlarının belirlenmesinde kültür etkilidir. yargılarından hangileri çıkarılabilir?","options":["Yalnız 1","Yalnız 2","1 ve 2","1 ve 3"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Girlevik Şelalesi, Erzincan’ın en çok ziyaret edilen yerlerindendir. (II) Özellikle bahar aylarında açan rengârenk küpe çiçekleri, şelalenin ziyaretçilerinde hayranlık uyandırıyor. (III) Kış aylarında hava sıcaklığı eksiye düştüğü için şelale donuyor. (IV) Şelalenin donmasıyla oluşan buz sarkıtları oldukça ilgi çekici görünüyor.","stem":"Bu metindeki numaralanmış cümlelerin hangilerinde öznel bir ifade vardır?","options":["I ve II","I ve III","II ve IV","III ve IV"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Işıklı Gölü, Denizli’nin Çivril ilçesinde yer almaktadır. (II) Bu göl doğal bir çöküntü alanı üzerinde oluşmuştur. (III) Kent merkezine 120 kilometre mesafede bulunan gölün alanı 3500 hektar civarındadır. (IV) Gölün kıyısına setler yapıldığından göldeki su seviyesi zamanla yükselmiştir.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde neden-sonuç ilişkisi vardır?","options":["I","II","III","IV"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Dışarıdan gelen kuş çığlıklarını duyunca pencereye yöneldim. (II) Binlerce kuşun gökyüzünden kapkara bir bulut gibi geçtiklerini gördüm. (III) Dünyadaki bütün kuşlar gökyüzündeydi sanki. (IV) Tek bir gövdeymiş gibi birlikte yükselip birlikte alçalıyorlardı.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde karşıtlık (tezat) vardır?","options":["I","II","III","IV"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Başlık bulma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Hepimizin rahatlıkla yapabileceği doğa yürüyüşü, hem tabiatla iç içe olup stresten arınmamızı hem de bedenimizi hareket ettirerek dinç kalmamızı sağlayan sporlardan biridir. Bizi hareketsizlikten ve şehirlerin gürültüsünden kurtarır. Gezmemizi, temiz havaya ve yeşile doymamızı sağlar.","stem":"Bu metne getirilebilecek en uygun başlık aşağıdakilerden hangisidir?","options":["Doğa Yürüyüşünün Faydaları","Doğa Yürüyüşü Koşulları","Doğa Yürüyüşünün Özellikleri","Doğa Yürüyüşünün Aşamaları"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Konu bulma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Mavi yengeçler, genellikle Atlas Okyanusu’nun Amerika kıtası kıyılarında yaşayan bir deniz canlısıdır. (II) Kabuğu mavi yeşil tonlarda olan bu yengecin beş çift bacağı vardır. (III) Kıskaçlı ön iki bacağını beslenmek için kullanır. (IV) Küreği andıran arka iki bacağı yüzme konusunda ustalık kazanmasını sağlar.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde benzetme vardır?","options":["I","II","III","IV"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Kışın yapılabilecek en heyecanlı sporlardan biri buz tırmanışıdır. Buz tutmuş şelaleler bu sporu yapmak için en elverişli yerlerdir. Bu sporu yapan kişiye buz kâşifi denir. Bu kişiler tırmanış esnasında buz çekici, buz kramponu, emniyet kemeri, buz vidası gibi malzemeler kullanır. Buz kâşifleri tırmanış yaparken kaygan yüzeyler, kırılgan buz kütleleri, soğuk ısırması gibi sorunlarla karşılaşabilirler. Bu sporla uğraşanlar zamanla dayanıklılık, bilgi ve tecrübe kazanır.","stem":"Bu metinde “buz tırmanışı” ile ilgili aşağıdakilerden hangisine değinilmemiştir?","options":["Yapılabileceği zamana","Kullanılması gereken malzemelere","Karşılaşılan sorunların çözümüne","Yapılması uygun yerlere"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Anlatım özellikleri","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Aşağıda verilen parçaların hangisinde anlatım üçüncü kişi ağzıyla yapılmıştır?","stem":"Doğru seçeneği işaretleyiniz.","options":["Adamın durduğu yere geldiğimizde önümüzde olağanüstü bir görüntü belirdi. Bulunduğumuz yerden iki yüz metre ötede sarmaşıklar içinde bir ev duruyordu.","Gözlerimi kâğıda çevirince yine aynı ses geldi. Hızla başımı kaldırdım. Hayır, bir şey yoktu.","Dükkâna vardığım zaman, henüz kapı açılmamıştı. Hemen bitişiğimizdeki fotoğrafçı ve kasap bir şeyler konuşuyorlardı.","Köprüye gelmişlerdi. Koşar gibi yürüyen bir kalabalık vardı. Haliç tarafındaki kaldırıma geçtiler. Arada sırada mavi sulara, irili ufaklı kayıklara bakıyorlardı."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Deri, vücudumuzu saran ve dış etkenlere karşı koruyan tabakadır. (II) Vücudumuzu bir yere şiddetli çarparsak derimizin altındaki kan damarları çatlar ya da yırtılır. (III) Bu durumda kanımız, derimizin altında sıkıştığından derimizin rengi maviye döner. (IV) İyileşme sürecinde de bu renk yeşilin tonlarını alır.","stem":"Bu metindeki numaralanmış cümlelerin hangisinde koşul anlamı vardır?","options":["I","II","III","IV"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Aşağıdakilerden hangisi bir paragrafın giriş cümlesi olabilir?","stem":"Doğru seçeneği işaretleyiniz.","options":["Bu sayede sürtünme kuvvetini bilmenin halatı güçlü çekmekten daha önemli olduğu anlaşıldı.","Kırlangıçlar ve balinalar gibi milyarlarca hayvan, yılın belli dönemlerinde, bulundukları yaşam alanlarından farklı bir yere göç eder.","Hatta bir bitkinin boyunun uzama miktarını ya da bir cismin sıcaklığının ne ölçüde değiştiğini belirlemek için de ölçüm yapabilirsiniz.","İnsanlık tarihinin şekillenmesinde ve tarihsel olayların günümüze kadar ulaşmasında da bu kalemler büyük bir rol üstlenmiştir."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"İlhanlılar Dönemi’nden günümüze ulaşan en önemli eserlerden biri Amasya Bimarhanesi’dir. Anadolu Selçuklu Dönemi’nin mimari özelliklerini taşıyan yapı, Anber Bin Abdullah tarafından yapılmıştır. Anadolu’da, hastalıkların tedavisinde müzik kullanılan ilk hastane olarak bilinmektedir. 2011 yılında müzeye dönüştürülerek Sabuncuoğlu Şerafettin Tıp ve Cerrahi Tarih Müzesi adıyla ziyarete açılmıştır. Müzede Sabuncuoğlu Şerafettin’in çizimlerinden yola çıkılarak yaptırılan 10 ayrı branştaki tıp ve cerrahi aletleri ziyaretçilerle buluşmaktadır.","stem":"Bu metinde “Amasya Bimarhanesi” ile ilgili aşağıdaki sorulardan hangisinin cevabı yoktur?","options":["Müze olarak hizmet vermeye ne zaman başlamıştır?","Hangi hastalıklar müzikle tedavi edilmiştir?","Sergilenen eserler nelerdir?","Kim tarafından yapılmıştır?"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Bir alanda yol alabilmek için o işin ustalarını tanımak ve yapıldığı çevrede gezmek gerekir. Şiir yazmak istiyorsan edebiyat sohbetlerine katılmalısın. Lezzetli yemekler yapmak için şeflerin mutfağında bulunmalısın. Kalıcı bir bina dikmekse amacın şehrin mimarisini görmeli, mimarları dost edinmelisin. Bir spor dalında ilerlemekse niyetin arkadaşların sporcular, mekânın spor alanları olmalıdır.","stem":"Bu metnin ana düşüncesi aşağıdakilerden hangisidir?","options":["Etrafımızda olan biteni anlamak için çevremizi dikkatli gözlemlemeliyiz.","Mesleğimizi seçerken başkalarının görüşlerini dikkate almalıyız.","Bir işte ustalaşmak o işin yapıldığı çevreye yakın olmakla mümkündür.","Bir işte başarılı olmak için çeşitli fedakârlıklarda bulunmak gerekir."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Bir genç, yaşlı bir ahbabıyla büyük bir binanın merdivenlerini çıkıyormuş. Yaşlı adam her basamağı çıkışında durup bir şeyler mırıldanıyormuş. Genç adam da onun yeni bir basamağa adım atmasını sabırsızlıkla bekliyormuş. Yaşlı adam bir ara dostuna dönerek şöyle demiş: – Sana benim bu hâlim garip geliyor değil mi? Hakkın var. Ben her basamağı çıktığımda Allah’ıma şükrediyorum. Sen şimdi bunun manasını anlayamazsın ama bir gün gelecek, sen de - - - - olduğunu anlayacaksın.","stem":"Bu parçada boş bırakılan yere anlam akışına göre aşağıdakilerden hangisi getirilmelidir?","options":["zorluklar karşısında sabretmenin çok büyük bir erdem","merdiven basamağı aşmanın dahi şükretmeye değer","yaşlılığın ve hastalığın ne kadar dayanılmaz bir azap","bu koca hayatta yalnız kalacak ve yalnızlığın ne demek"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Konu bulma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Atatürk bir gün çocuk balosuna gider. Küçük bir çocuk salonun orta yerinde kalır. Bu yavru hayranlıkla bir süre Atatürk’e baktıktan sonra, “Ata’m, seni öpmek istiyorum.” der. Ortalığa bir sessizlik dalgası yayılır. Bu derin sessizliği Atatürk’ün sesi bozar: “Öyleyse, gel öp!” Çocuk koşarak Atatürk’ün boynuna sarılır. O sırada diğer çocuklar da, “Biz de… Biz de...” diye bağırırlar. Böylece tüm çocuklar Ata’yı doya doya öperler. Bu görüntü çoğu kişiyi ağlatır. Büyük Atatürk de ağlar. Evet, Türk çocuklarının bu engin sevgisi için ağlar. Hem de sevinç gözyaşlarını dökerek. O gün çevresindekilere övünçle, “İşte benim kuşaklarım!” der.","stem":"Bu parçanın konusu aşağıdakilerden hangisidir?","options":["Atatürk’ün çocukların gelişimine verdiği önem","Türk çocuğunun Atatürk sevgisi","Türk çocuğunun cesareti","Atatürk’ün sanata olan ilgisi"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Günümüz çocuklarının elinden akıllı telefonlar, tabletler düşmüyor. Hangi aileye gitsem evin çocuğu elindeki cihaza gömülmüş, çeşit çeşit oyun oynuyor. Eskiden ekonomik düzeyi yüksek ailelerin çocuklarının erişebildiği bu imkânlar, akıllı telefonlar ve ekonomik internet paketleri ile her cebe girmiş durumda. Hâl böyle olunca artık çocukların oyun oynamak için sokağa çıkmasına gerek kalmadı. Böylece günümüz çocuklarında oyun bağımlılığı yaygınlaştı.","stem":"Buna göre çocuklarda oyun bağımlılığının yaygınlaşmasının nedeni aşağıdakilerden hangisidir?","options":["Teknolojinin gelişmesinden ötürü teknolojik olanakların ucuzlaması ve yayılması","Ebeveynlerin çocuklarının arzu ve beklentilerini engelleyememesi","Bilgisayar piyasasındaki oyun çeşitliliğinin oldukça fazla olması","Çocukların dış dünyanın tehlikelerinden korunmak istenmesi"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Girdikleri yere neşeyi de beraber getiren insanlar vardır; güler, söyler, bir şeye aldırmazlar. (II) Hatta mutsuz bir şekilde oturanları veya zihinleri bir şeye takıldığı için düşünmekte olanları bile “Ne düşünüyorsunuz, binin yarısı beş yüz, o da biz de yok!” deyip neşelenmeye davet ederler. (III) Kara kara düşünmekten bir şey çıkmaz. (IV) Olsa olsa başkalarının da neşelerinin kaçmasına sebep olur.","stem":"Bu parçada numaralanmış cümlelerin hangisinden sonra “Aslına bakarsanız işin doğrusu da budur.” cümlesi getirilirse parçanın anlam akışı bozulmaz?","options":["I.","II.","III.","IV."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Ünlü bir bilgin öğrencilik yıllarında dersleri anlayamadığından kendisini başarısızlığa mahkûm etmişti. Üzüntüyle memleketine dönerken mola verdiği bir mağaranın tavanından düşen su damlalarının zemindeki sert taşta derin bir çukur açtığını gördü ve düşünmeye başladı: — Damlalar taşa iz bırakırda, çalıştığım dersler benim kafamda nasıl iz bırakmaz? Öyleyse bu su damlaları gibi yılmadan çalışmalıyım. Hemen geri döndü ve hedefe ulaşmak için kararlılıkla çalışmaya başladı. Neticede büyük bir bilgin olarak tarihteki yerini aldı. Everest Dağı’na çıkma girişimi başarısızlıkla sonuçlanmış bir dağcı, bu girişiminden sonra İngiltere’de bir okulun öğrencilerine konuşma yapmak için çağrıldı. Konuşma sırasında bir ara konuşma kürsüsünün yanında duran Everest’in büyük boy fotoğrafının önüne doğru yürüdü. Sonra fotoğrafa dönüp yüksek sesle koca zirveye meydan okudu: “Beni ilk denememde yendin ama bitmedi, bekle, seni bu kez ayaklarımın altına alacağım.” Bu konuşmadan bir yıl sonra Everest, bu dağcının ayakları altındaydı.","stem":"Aşağıdakilerden hangisi, bu metinlerin ortak yönlerinden biri değildir?","options":["Azim konusunu ele alması","Öyküleyici anlatıma başvurulması","Bir gerçeği ortaya çıkarmak için yazılması","III. kişi ağzından anlatılması"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Olay: Bir annenin çoçuğunun yüksek ateşini düşürmesi Yer: Ev Zaman: Kış, gece Kişiler: Emine ve kızı Elif Anlatıcı: III. Kişi","stem":"Aşağıdaki metinlerden hangisi bu yapı unsurlarına uygun olarak kurgulanmıştır?","options":["Emine, soğuk bir kış gününün gece yarısında kızı Elif’in inlemesiyle uyandı. Kızına sarıldı. O da ne? Elif’in ateşi yüksekti. Önce kızın üzerindeki yorganı açtı, sonra kalın giysiyi soydu, ardından koltuk altlarına ve alnına el havlusunu ılık suya batırıp koydu. Elif bir an irkilip ağlamaya başladı. Bu hamleyle Elif’in ateşi biraz düşse de bu durum çok sürmedi, ateş tekrar yükseldi. Emine bu defa Elif’e ılık suyla güzel bir duş aldırdı. Böylece Elif’in ateşi düştü.","Elif’e “Kış geldi artık, kalın giyinmelisin.” desem de bir türlü dinletemiyordum. Akşam olunca Elif’in ateşi olduğunu fark ettim. Hemen eşimle beraber acile gittik. Doktor ateşini ölçtükten sonra kızıma bir ateş düşürücü şurup içirdi ve Elif’i gözetim altında tutacaklarını söyledi. O geceyi Elif’in ateşi kontrol altına alınıncaya kadar hastanede geçirdik.","Gök gürlemesiyle gecenin bir yarısında uyandım. Üşüdüğümü hissettim. “Kış geldi artık.” dedim. Yataktan doğrulmamla annem odama girdi. “Neyin var canım?” diyerek alnıma dokundu. “Ateşin var senin.” dedi. “Ama üşüyorum.” deyince “Ateşten.” diye üsteledi. Odadan çıktı, birkaç dakika sonra elinde bir sünger ve bir tas su ile geldi. Süngeri suya batırıp sıktı, alnımı ve ensemi sildi. Biraz sonra kendimi daha iyi hissediyordum.","Güneş ufuktan doğmuştu. Emine sessizce kalktı. Vakit çok erken olduğundan kızı Elif’i uyandırmak istemiyordu. Ona güzel bir sabah kahvaltısı hazırlamak içi kolları sıvadı. Tost, peynir, zeytin… Her şey vardı kahvaltıda. Az sonra Elif’in odasına yavaşça girdi. Elif yorganını başına çekmişti. Emine şaşırdı. Oda pek soğuk sayılmazdı. Yorganı aralayıp elini kızının alnında gezdirince Elif’in ateşi olduğunu anladı."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Meşhur bir Paris terzisi, gençliğinde fakir ve küçük bir terzi kalfası olarak işe başlamış. Kısa zamanda terzilik mesleğinde hayli hüner elde etmiş. Ancak hiç parası olmadığından kendi işini bir türlü kuramamış ve gündelikle çalışmaya devam etmiş. Derken günün birinde zengin bir adam karşısına çıkmış ve kendisine iş kurması için para vereceğini söylemiş. Genç terzi “fırsat bu fırsat” demiş ama hemen bu paranın üzerine atılmamış. Bu teklifi edene öyle şartlar ileri sürmüş; kuracakları işin gereklerini yerine getirmek, ona mükemmel bir hâlde başlamak için öyle düzenlemeler hazırlamış ki bu sayede kısa zamanda Paris’in en meşhur terzisi olmuş.","stem":"Bu parçanın ana düşüncesi aşağıdakilerden hangisidir?","options":["Hayatta başarılı olabilmek için mal mülk sahibi olmak gerekir.","Yeteri kadar parası olmayan birinin kendi işini kurması olanaksızdır.","Herkesçe bilinen, saygı duyulan bir birey olmanın tek yolu becerikli olmaktır.","İş hayatında başarılı olmak isteyen kişi önüne çıkan fırsatları iyi değerlendirmelidir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Metin türleri","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Anı; yaşanmış olayların, üzerinden belli bir zaman geçtikten sonra anlatıldığı yazı türüdür.","stem":"Buna göre aşağıdakilerden hangisi anıya örnek olamaz?","options":["Sonunda bayram geldi. Bu bayram benim için diğerlerinden güzel geçeceğe benziyor. Birazdan en güzel elbiselerimi giyip dışarı çıkacağım. Arkadaşımla buluşup komşularımızı ziyaret edeceğiz. Sonra da ver elini lunapark...","Benim yaşımda olanlar iyi bilir. Eskiden, kara lastik denen ayakkabılar vardı. Bu ayakkabıların bir iki numara büyüğünü alırdı babam bana. Böylece ayakkabıyı en az iki üç yıl giyerdim. Arkadaşlarımla birbirimizin ayakkabısını giydiğimiz de çok olmuştur.","Okula başladığım ilk günü daha dünmüş gibi hatırlıyorum. O gün bende beliren en baskın duygu sevinçti. Çünkü babamın her gün dikkatle okuduğu gazetedeki yazıları okuyabilecek, harçlıklarımı sayabilecektim artık.","Yağışlı bir gündü. Yağmurda ıslanmış küçücük bir kedi yavrusu bulmuştuk sokakta. Acıdığımız için eve getirmiştik. Kedi, o denli küçüktü ki adını Damla koyduk. Damla, büyüdü, büyüdü; damla olmaktan çıktı, bir göl oldu. Ona ne süt yetiştirebildik ne de mama..."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Yaşlanmanın birçok nedeni vardır. Bunlardan biri, dokuları yenilemek amacıyla bölünen hücrelerdeki kromozomları koruyan telomer adındaki yapıların kısalmasıdır. Çevresel faktörler, genetik özellikler ve beslenme alışkanlıkları da yaşlanma sürecini etkiler. Yaş ilerledikçe vücutta pek çok değişim gerçekleşir. Ciltte kırışma, saçlarda beyazlama, kulaklar ve burunda büyüme, boy kısalması ve görme yetisinin azalması akla ilk gelenlerdir. Bu değişimlerin oluşma hızı herkeste aynı değildir.","stem":"Bu parçada “yaşlanma”yla ilgili aşağıdakilerden hangisine değinilmemiştir?","options":["Sebeplerinin neler olduğuna","Her insanda farklı hızda gerçekleştiğine","İnsanda ne tür değişikliklere yol açtığına","Gerçekleşmesinde etkili olan çevresel faktörlere"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Belirli bir bölgede yaşayan bitki ve hayvan türlerinin sayıca zenginliği olarak tanımlanan biyoçeşitlilik, genetik çeşitlilikle tür ve ekosistem çeşitliliğini kapsar. Bilim insanları, dünyamızın yaşanabilir bir hâlde kalması için biyoçeşitliliği koruma çalışmaları yapmaktadır.","stem":"Bu metne göre aşağıdakilerin hangisi biyoçeşitliliğin korunması için yapılacak çalışmalardan biri olamaz?","options":["Üretimde modern tarım tekniklerinin kullanılması","Nesli tükenmekte olan hayvanların güvenli ortamlarda çoğaltılması","Aşırı avlanmayı önlemek için caydırıcı yasal düzenlemelerin yapılması","Belirli tabiat alanlarının yerleşime kapatılması"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Empati (duygudaşlık), kişinin kendisini karşısındaki insanın yerine koyarak onun duygu ve düşüncelerini anlama çabasıdır.","stem":"Buna göre, Çocuk: — Günüm güzel geçtiği için keyfim yerinde, anne! Anne: — - - - - metninde, anne aşağıdaki cevaplardan hangisini verirse çocuğuyla empati kurmuş olur?","options":["Kardeşin de geçen gün aynı cümleyi söyledi.","İşler yolunda gittiği için mutlu hissediyorsun, değil mi?","Arkadaşların da senin gibi mi düşünüyor acaba?","Anlat bakalım, bugün neler yaşadın?"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Anlatım özellikleri","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"İnsanların gözünde “retina (ağ tabaka)” adı verilen bir bölüm bulunur. Bu bölümün üzerinde ışığa duyarlı hücreler vardır. Bu hücreler, üzerlerine düşen ışığın bir kısmını emerek yok eder. Işığın yok olmayan bölümüyse ağ tabakanın arkasına geçer. Bazı hayvanların gözlerinde insanlarınkinden farklı olarak ağ tabakanın arkasında bir tabaka daha bulunur. Bu tabaka, ışığı bir ayna gibi yansıtır. Bu yüzden geceleri ışık vurduğunda bazı hayvanların gözleri parlar.","stem":"Bu metnin anlatımıyla ilgili aşağıdakilerden hangisi söylenemez?","options":["Bir durumun nedeni açıklanmıştır.","Karşılaştırmaya başvurulmuştur.","Tanımlama yapılmıştır.","Açıklayıcı anlatımdan yararlanılmıştır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Çocuk, karşılaştığı her eşya ve durum karşısında şaşkındır; yeni bir gözle bakar her şeye. Şairlerin dünyaya bakışı da böyle olmalı. Çünkü dünyaya alışmak şair bilincini köreltir.","stem":"Bu parçada asıl anlatılmak istenen aşağıdakilerden hangisidir?","options":["Çocukların dünyası, şairleri besleyen en önemli unsurlardandır.","Şair, günlük olaylara farklı açılardan bakmayı bilmelidir.","Gerçeklikle bağını koparmayan şair daima başarıya ulaşır.","Şair, dünyaya çocuksu bir merakla bakmalıdır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Zekâ, insanları birbirinden farklı kılan özelliklerdendir fakat boy, kilo, saç rengi gibi doğrudan gözlemlenemez. Bu yüzden zekânın tanımını yapmak ve zekâyı ölçmek karmaşık bir iştir. Buna rağmen zekâyı ölçmek için çeşitli zekâ testleri geliştirilmiştir. Gazete, dergi ve çeşitli internet sitelerinde zekâ testi olduğu söylenen birtakım testlere sıklıkla rastlanır. Bunlar gerçek zekâ testleri değil, kişilerin dikkatini çekmek üzere hazırlanmış sözde testlerdir. Gerçek zekâ testleri, yıllar süren bilimsel araştırmalar sonucu geliştirilir. Bu testleri sadece konunun uzmanı kişiler, belirli bir eğitim aldıktan sonra uygulayabilir.","stem":"Bu parçada aşağıdaki sorulardan hangisinin cevabı yoktur?","options":["Sözde zekâ testleri kimlere uygulanır?","Gerçek zekâ testleri nasıl hazırlanır?","Zekâyı ölçmek niçin zor bir iştir?","Zekâ ölçülebilir mi?"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Aydın kimliğiyle tanınan yazarın yeni kitabı, geçtiğimiz günlerde edebiyatseverlerle buluştu. Birçoğumuzun beyaz perdeden tanıdığı yazar, kamera önünde ve arkasında yaptığı çalışmalarla da adından söz ettiriyor. Ancak onun her şeyden önce gerçek bir edebiyatçı olduğu gözden uzak tutulmamalı. Kendi deyişiyle, ilgilendiği tüm alanlardaki eserleri edebiyattan beslenir.","stem":"Bu metinde sözü edilen yazarla ilgili aşağıdakilerden hangisi söylenemez?","options":["Çok yönlü bir kişiliğe sahiptir.","Birden çok eser kaleme almıştır.","Edebiyatı diğer alanlar için kaynak olarak kullanmaktadır.","Yeni eserini sinemaya aktarmayı düşünmektedir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Farklı düşünme yollarının öğretildiği bir etkinlikte, farklı renklerde şapkalar kullanılmış ve öğrencilere şapkaların özellikleri aşağıdaki gibi açıklanmıştır: Beyaz şapka: İstatistiki veriler sunar. Sarı şapka: Olaylara iyimser bakar ve olayların olumlu yönlerini görür. Siyah şapka: Olaylara kötümser bakar, olayların olumsuz yönlerini görür. Kırmızı şapka: Olaylara duygusal tepkiler verir. Öğrencilerden “teknolojik aletler” hakkındaki düşüncelerini, taktıkları şapkalara göre açıklamaları istenmiştir.","stem":"Bu metne göre aşağıdaki öğrencilerden hangisinin cümlesi yay ayraç içinde verilen şapkaya uygun değildir?","options":["Işıl: Son verilere göre Türkiye’de 15-18 yaş arası kişilerin teknolojik aletlerin başında geçirdiği süre günde yaklaşık üç saattir. (Beyaz şapka)","Mehmet: İnsan hayatını kolaylaştırdığı düşünülen teknolojik aletler aslında insanı tembelliğe itmektedir. (Sarı şapka)","Gamze: Teknolojik aletler, sosyal ilişkilerimizin zayıflamasına neden olmaktadır. (Siyah şapka)","Ayşe: Almanya’daki babaannem ile görüntülü konuşup özlem gidermek müthiş bir şey! (Kırmızı şapka)"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Çağ Açıp Çağ Kapatan Padişah Fatih Sultan Mehmet İstanbul’un fethiyle dünya tarihini değiştirip yeniden şekillendiren Fatih Sultan Mehmet; kişiliği, devlet adamlığı ve askerî dehasıyla dünyanın en büyük liderlerinden oldu. 30 Mart’ta Edirne’de dünyaya geldi. Babası Sultan II. Murat’ın isteğiyle 12 yaşında tahta çıktı. Ülkenin genel durumu ve yaşının küçük olması nedeniyle yaklaşık iki yıl kadar tahtta kaldı ve padişahlığı kendi isteğiyle babasına devretti. 19 yaşında yeniden padişah oldu. 880 bin kilometrekare olan Henüz 21yaşındayken Osmanlı toprakları, yüzyıllardır ele geçirilemeyen onun döneminde 2 milyon 214 bin İstanbul’u elli dört günlük kilometrekareye ulaştı. bir kuşatmanın ardından fethederek “Fatih” unvanını aldı. Hükümdarlığı döneminde âlimlere sahip çıkan Fatih Sultan Mehmet; matematik, coğrafya, astronomi, ﬁzik gibi pek çok alanda yetenekli ve bilgi sahibi 3 Mayıs’ta Gebze yakınlarında bulunan bir entelektüeldi. Hünkâr Çayırı’ndaki ordugâhında 49 yaşında vefat etti.","stem":"Bu metinden Fatih Sultan Mehmet’le ilgili aşağıdakilerin hangisine ulaşılamaz?","options":["Bilim insanlarına değer vermiş bir padişahtır.","Dünya tarihindeki en önemli liderlerden biridir.","Genç yaşında “Fatihˮ unvanını almıştır.","Osmanlı topraklarını en geniş sınırlarına ulaştırmıştır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Bir adam, suda bata çıka ilerlemeye çalışan bir akrep görür. Onu kurtarmaya karar verip parmağını uzatınca akrep onu sokar. Adam, akrebi tekrar kurtarmaya çalışır, akrep onu yeniden sokar. Bunu gören biri, adama “Seni sürekli sokmasına rağmen onu hâlâ neden kurtarmaya çalışıyorsun?” diye sorduğunda şu cevabı alır: “Sokmak, akrebin doğasında vardır. Benim doğamda ise sevmek ve yardım etmek var. Sokmak akrebin doğasında var diye kendi doğamda olandan niçin vazgeçeyim?”","stem":"Bu metinle ilgili aşağıdakilerden hangisi söylenemez?","options":["Günlük hayatta rastlanabilecek bir olay anlatılmıştır.","Ders vermek amacıyla oluşturulmuştur.","Karşılıklı konuşmaya yer verilmiştir.","Olayın gerçekleştiği zaman bellidir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Çocukluğumda kış mevsimi gelince babam beni bahçelere götürür; yaprakları dökülmüş, sadece gövdesi ve dalları kalmış ağaçların isimlerini sorardı bana. Bilirsem neşelenir, dönüşte bir şeyler ısmarlardı. O vakitler buna bir anlam veremezdim ama artık anlamını biliyorum. Babam aslında ağaçları değil, insanları öğretiyordu bana. İşin hikmeti buydu. Ağaçlar üzerinden insanları tanıma sanatı… Dalların meyve doluyken seni herkes tanır ve severdi. Yaprakların gölge verdiğinde yanına gelen, senden istifade eden çok olurdu. Kış ise zor günler, ağır şartlar demekti. İnsanlara verebileceğin yahut onların senden alacağı hiçbir şey yoktu. Zor zamanlarda da seni seven ve sana kucak açanlar hakiki dostların demekti.","stem":"Bu metinde anlatılanlar aşağıdaki atasözlerinden hangisiyle ilişkilendirilebilir?","options":["Dost, kara günde belli olur.","Dostun attığı taş, baş yarmaz.","Dost ile ye, iç; alışveriş etme.","Dost başa, düşman ayağa bakar."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Güneşin zararlı ışınlarından korunmak için ya bir gölgeye sığınıyor ya da cildimize güneş koruyucu krem sürüyoruz. (II) Fakat güneşten korunmanın, sağlığımız için bir risk oluşturduğu fikri önem kazanmaya başladı son yıllarda. (III) Dünya çapında büyük oranda artan D vitamini eksikliğinin, insanların güneşten korunmaya çalışmasından kaynaklandığı ortaya çıktı. (IV) D vitamini eksikliği, beraberinde güçsüz kemik ve dişleri, enfeksiyonları, kalp ve damar hastalıklarını getiriyor.","stem":"Bu metinde numaralanmış cümlelerle ilgili aşağıdakilerden hangisi söylenemez?","options":["I. cümlede bir tespitte bulunulmuştur.","II. cümlede düşüncenin yönü değişmiştir.","III. cümlede neden-sonuç ilişkisi söz konusudur.","IV. cümlede karşılaştırma yapılmıştır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Çıkarım yapma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Penisilinin keşfi, 1927 yılında A. Fleming’in ilginç bir gözlemine dayanır. İçerisinde mikrop ürettiği kapları inceleyen Fleming, bunlardan birinin üzerinde mavi renkli bir küf oluştuğunu ve bu küfün çevresinde hiç mikrop üremediğini fark etti. Bu ilginç olayı araştıran Fleming, küflenmiş peynirlerin üzerinde de oluşan bu mavi küfün içindeki mikroorganizmaların, mikropları öldürdüğünü buldu. Buna penisilin adını verdi. Penisilinin yapay olarak elde edilmesi ise 1940 yılında gerçekleşti.","stem":"Bu metinden penisilin ile ilgili aşağıdakilerin hangisine kesin olarak ulaşılır?","options":["Bir tesadüf sonucu keşfedildiğine","Süt ürünlerinde daha çok bulunduğuna","Birçok hastalığın tedavisinde kullanıldığına","Yapay hâlinin Fleming tarafından üretildiğine"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Son dönemde tarih ve kültür ağırlıklı kitaplar okuyorum ama aslında seyahatnameleri, günlük ve otobiyografileri severim. Yerli ya da yabancı fark etmez. Tekrar tekrar okuduğum yazarlar da var: Sait Faik, Refik Halit, Çehov, Sabahattin Ali… Rus klasiklerine ise yol haritası ya da pusula gözüyle bakarım.","stem":"Bu parça aşağıdaki sorulardan hangisinin cevabıdır?","options":["Okuduğunuz yazarların yerli ya da yabancı olması sizin için önemli midir?","Hangi yazarları ve ne tür kitapları okumayı tercih ediyorsunuz?","İyi bir kitabın hangi özellikleri taşıması gerektiğini düşünüyorsunuz?","Tarih ve kültür ağırlıklı kitapları okumak okura bir şey kazandırır mı?"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Farklı alanlarda ortaya koyduğum ürünlerin hepsi de edebiyattan besleniyor. Sanki edebiyat atına binmişim; senaryodan oyunculuğa, şiirden hikâyeye, denemeden romana koşturup duruyorum. Beni her yere edebiyat taşıyor.","stem":"Bu parçada yazarın, kendisiyle ilgili asıl anlatmak istediği aşağıdakilerden hangisidir?","options":["Edebiyatı diğer sanat dallarından üstün tuttuğu","Sanatsal gücünün ve kaynağının edebiyat olduğu","Edebiyat ürünlerini diğer sanat alanlarına uyarladığı","Edebiyatı sinemaya geçişte araç olarak gördüğü"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Anılarımın bu kadar canlı ve zengin olmasına çoğu zaman şaşırıyordum. Onları yazıya dökmeden önce ayıklamak için epey çaba harcadım. Ama bu daha çok, metni kelime yükünden nasıl kurtarabilirim çabasıydı.","stem":"Bu parçadaki “metni kelime yükünden kurtarmak” sözüyle anlatılmak istenen aşağıdakilerden hangisidir?","options":["Daha özlü bir anlatımı tercih etmek","Süsten ve yapay anlatımlardan kaçınmak","Türün gereklerine uygun biçimde yazmak","Bazı alanları okurun yorumuna bırakmak"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Binlerce bacadan henüz tütmüş soğuk, nemli bir duman kadar koyu bir sis her tarafı kaplamıştı. Ordugâh, sancaklar, tuğlar, çadırlar, dişbudak ağaçları, atlar, hiç, hiçbir şey görünmüyordu. Evvela birbirlerini çağıranların sözleri duyuluyor, sonra iki hayal, ses yordamıyla bu beyaz karanlığın içinde buluşuyordu. Arslan Bey atını hazırlatmıştı. Yine yapayalnız, her gün gittiği yere doğru kaybolacaktı.","stem":"Bu metinle ilgili aşağıdakilerden hangisi söylenemez?","options":["Hikâye türünde yazılmış metinden alınmıştır.","Betimleyici anlatımdan yararlanılmıştır.","Zaman unsuru belirgin değildir.","Anlatım birinci kişi ağzından yapılmıştır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Güney Atlantik kambur balinası nüfusu, aşırı avlanmadan 1900’lü yıllarda hızlı bir düşüş yaşamış. (II) Bu üzücü düşüş neyse ki türün koruma altına alınmasıyla durmuş ve bir süre sonra balina sayısı artmaya başlamış. (III) Öyle ki Uluslararası Balina Avcılığı Komisyonu tarafından yapılan yeni bir çalışmaya göre yaklaşık 25.000 Güney Atlantik kambur balinası artık kendi yaşam alanlarında yüzüyor. (IV) Araştırmacılar 2030 yılına gelindiğinde bu sayının daha da artacağını söylüyor.","stem":"Bu parçadaki numaralanmış cümlelerle ilgili aşağıdakilerden hangisi söylenemez?","options":["I. cümlede neden-sonuç ilişkisi vardır.","II. cümlede karşıt iki durumdan söz edilmiştir.","III. cümlede öznel anlatımdan yararlanılmıştır.","IV. cümlede bir öngörüye yer verilmiştir."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Sabun üretiminde iki yöntem vardır: Sıcak yöntemde, yağ ile küllü su uzun süre kaynatılır ve istenmeyen maddeler yüzeye çıktıkça toplanır. Bu işlem sabun tamamen arındırılıncaya kadar sürdürülür. İşlem bitiminde sıcak sıvı sabun, kalıplara dökülür ve katılaşması için dinlenmeye bırakılır. Soğuk yöntemde ise küllü suya, eritilmiş yağ eklenir ancak bu karışım kaynatılmaz. Karışım belirli bir kıvama gelinceye kadar karıştırılır ve ardından kalıplara dökülerek bir süre beklenir. Daha sonra sabun, kalıplardan çıkarılır ve kuruması için birkaç hafta bekletilir. Soğuk yöntemle üretilen sabunlarda arındırma yapılamadığından bu sabunlar kişisel temizlik için tercih edilmez.","stem":"Bu metne göre üzerinde “Küllü suya, eritilmiş yağ eklenerek üretilmiştir.” yazan bir sabunla ilgili aşağıdakilerden hangisi söylenebilir?","options":["Soğuk yöntemle üretilmiştir; küllü su, yağ ile uzun süre kaynatılmıştır.","Sıcak yöntemle üretilmiştir, yağ ve küllü su uzun süre kaynatılmıştır.","Soğuk yöntemle üretilmiştir, kaynatılmadan kalıplara dökülmüştür.","Sıcak yöntemle üretilmiştir, kişisel temizlik için uygundur."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Konu bulma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Günümüzde çocuklar oyuncaklardan çok, telefon ve tablet gibi akıllı cihazlarla oynuyor. Bu durumun, çocukları nasıl etkilediği ile ilgili bir araştırma yapıldı. 9-10 yaş grubu 11 bin çocuğun 5 yıl boyunca izlendiği bu araştırmayla çocukların ekran başında geçirdikleri sürenin, duygusal gelişimlerine ve beyinlerinin fiziksel yapısına olan etkileri ortaya çıkarıldı. Çalışmanın ilk aşamasında 4.500 çocuğun beyin filmi çekildi. Ekran başında günde yedi saatten fazla vakit geçiren çocukların beyinlerinin en dış katmanının erken incelmeye başladığı tespit edildi. Bunun ne anlama geldiği konusunda şimdilik bir yargıya varmak mümkün değil. Öte yandan ekran başında günde iki saatten fazla vakit geçiren çocukların düşünce ve dil testlerinde daha düşük puanlar aldığı görüldü.","stem":"Bu metinde sözü edilen araştırmanın amacı aşağıdakilerden hangisidir?","options":["Dijital aygıtların çocuklar için zararlı olduğunu ispatlamak","Oyuncakların akıllı cihazlardan yararlı olduğunu göstermek","Akıllı cihazların çocuklar üzerindeki etkisini belirlemek","Çocuklarda zihin ve dil gelişiminin önemini ortaya koymak"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Düşünceyi geliştirme yolları","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"İyimserlik ve olumlu tutum, birbirine yakın kavramlar gibi görünse de çok temel bir farklılık içerir. İyimserlik, işler zorlaştığı zamanlarda bile kişide olumlu duyguların hâkim olması ve kişinin, içinde bulunduğu zorluğu er geç aşacağına inanmasıdır. Olumlu tutum ise gelecekten çok, şimdiye ve geçmişe odaklanmaktır.","stem":"Bu parçada kullanılan düşünceyi geliştirme yolları aşağıdakilerin hangisinde verilmiştir?","options":["Benzetme - Karşılaştırma","Tanık gösterme - Örnekleme","Örnekleme - Tanımlama","Karşılaştırma - Tanımlama"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Hikâye unsurları","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"• Olay, kişi, zaman ve yer unsurları kullanılmıştır. • Anlatım, birinci kişi ağzından yapılmıştır. Aşağıdaki metinlerin hangisinde bu özelliklerin tümü yer almaktadır?","stem":"Doğru seçeneği işaretleyiniz.","options":["Emekli ikramiyesini aldığım gün yıllardır hayalini kurduğum tatile çıkmaya karar verdim. Artık istediğim gibi gezebilirdim. Pasaport ve vize işlemlerini önceden halletmiştim. Doğu ülkelerini merak ediyordum. Azerbaycan’dan başlayıp Japonya’ya kadar gitmeyi planlıyordum.","Sabahın erken saatleriydi. Otların üzerindeki çiğ damlaları dizlerimizi ıslatırken dedemle ben yaylaya doğru yola çıktık. İnek ve koyunların sesleri arasında şarkı söyleyerek yürüyorduk. Serin hava, ciğerlerime dolarken aniden bir sis bulutu yolumuzu kesti.","Otobüs, virajları dönerken sanki yola zar zor sığıyordu. Hele bir de karşıdan büyük bir araç gelirse durup yol vermek gerekiyordu. Bu şekilde süren zorlu bir yolculuğun ardından görev yerime ulaştım.","Sıradan bir Beyoğlu akşamında kalabalıklar cadde boyunca yürüyordu. Meydan; seyyar tezgâhlarda nohut, pilav, simit, midye, kokoreç satanlarla doluydu. Turistler tezgâhların yanına merakla gelip bu lezzetleri denemek için sanki yarış içindeydi."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Anneler, çocuklarına sütleri ve sevgileri kadar güzel, onlar kadar besleyici bir şey daha verirler: dil. (II) Analardan öğrenildiği için bir insanın kendi diline “ana dili” denir. (III) Biz, daha sonra istersek başka dilleri de öğrenebiliriz ama onlar hiçbir zaman ana dilimizin yerini tutmaz. (IV) Ana dil bizi ailemize, akrabalarımıza, milletimize, tarihimize bağlar.","stem":"Bu metinde numaralanmış cümlelerle ilgili aşağıdakilerden hangisi söylenemez?","options":["I. cümlede karşılaştırma yapılmıştır.","II. cümlede tanıma yer verilmiştir.","III. cümlede neden-sonuç ilişkisi kurulmuştur.","IV. cümlede mecazlı bir anlatım söz konusudur."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"“Mış gibi” yapmamalıydım. Elimdeki metni sıkı bir ezberle aktarmaya çalışmak yerine, sadece gerçek hayata yakın bir oyun çıkarmalıydım. Canlandırdığım kişi, hayatın içinden olmalıydı. Oyunculuktan anladığım şeyi tek bir cümlede şöyle ifade edebilirim: - - - -","stem":"Bu parçanın sonuna düşüncenin akışına göre aşağıdakilerden hangisi getirilmelidir?","options":["Yönetmenin sizden ne istediğini anlayıp içselleştirmeden rolünüzün hakkını veremezsiniz.","Seyirci, oynadığınız karakterle, sinemadan çıkar çıkmaz karşılaşabileceğine inanmalıdır.","Canlandırdığınız karakterin ne kadar gerçekçi olduğu önemli değildir, önemli olan sizin o karaktere ne kattığınızdır.","Seyircilerin, sinema salonundan mutlu bir şekilde ayrılması doğru bir iş çıkardığınız anlamına gelir."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"“Nedenler Ansiklopedisi” isimli kitapta farklı alanlara ait pek çok bilgi, sebep-sonuç ilişkisi çerçevesinde okuyucuyla buluşturulmuştur.","stem":"Buna göre aşağıdakilerden hangisinin sözü edilen ansiklopedide yer alması beklenmez?","options":["Bazı bilim insanları Ay’ın, Dünya ile bir başka gök cisminin çarpışması sonucu açığa çıkan parçacıkların birleşmesiyle oluştuğunu varsayıyor.","Kuyruklarında bulunan pervaneler, helikopterlerin havada dengeli şekilde kalmasını ve hareket etmesini sağlayan mekanizmalardır.","İzmir’in Selçuk ilçesine bağlı Efes Antik Kenti’ndeki tarihî kütüphane, en çok rağbet gören yapılar arasındadır. Kütüphanenin, İyonya Dönemi’ne ait olduğu tahmin edilmektedir.","Uçmak insanların birçoğuna keyif verir. Ancak yerden yükselince atmosfer basıncı, sıcaklık ve havanın içindeki oksijenin azalması insan sağlığı üzerinde olumsuz etkilere yol açabilir."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Çıkarım yapma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Uzaya gönderilen ilk canlı, Layka isimli bir köpek; uzaya çıkan ilk insan Kozmonot Yuri Gagarin’dir. İlk uzay yürüyüşü ise Aleksey Leonov tarafından 1965’te gerçekleştirildi. 1960’lı yıllarda başlayan insanlı uzay uçuşlarında bugüne dek birçok astronot ve kozmonot görev aldı. Hepsi de görevlerini güvenli bir şekilde yerine getirebilmeleri için tasarlanmış özel uzay giysileri giydi.","stem":"Bu metinden aşağıdaki bilgilerden hangisine kesin olarak ulaşılır?","options":["Uzay uçuşlarında görev alan kozmonot ve astronotlar, uzun süren eğitimlerden geçirilir.","Uzaya çıkan ilk insan olan Yuri Gagarin, bunu 1961’de gerçekleştirmiştir.","Uzay giysileri ilk olarak 1960’ta tasarlanmıştır.","Uzaya insandan başka canlılar da gönderilmiştir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Büyük fedakârlıklar yaparak geleceğimizi daha iyi şekillendirmek için azimle çalışırız. Bu durum bazen bizleri yorar, bıktırır ama “- - - -” sözü aklıma gelince daha bir gayrete gelirim.","stem":"Bu metinde boş bırakılan yere aşağıdakilerden hangisi getirilmelidir?","options":["Gökkuşağını görmek için yağmura katlanmak gerekir.","Bir mum diğer mumu tutuşturmakla ışığından bir şey kaybetmez.","Gerçek dostlar yıldızlar gibidir, karanlık çökünce ortaya çıkarlar.","Sağlıktan büyük zenginlik yoktur."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Aşağıdaki parçalardan hangisi “Hava tamamen kapalıysa yönümüzü nasıl bulacağız?” sorusunun yanıtı olabilir?","stem":"Doğru seçeneği işaretleyiniz.","options":["Güneş, doğuşundan batışına dek gökyüzünün güneyinde bir yay çizer. Öğle vaktinde tam güneydedir. Güneş’in doğrultusunu, o anda güneybatıyı gösteren bir pusula olarak kullanabilirsiniz ya da yere bir çubuk dikerseniz çubuğun gölgesi tam zıt yöne yani kuzeydoğuya düşer.","Nemli ve serin ortamı seven yosunlar, güneş ışınlarının yansıdığı bir ağacın güney tarafını değil kuzey tarafını tercih eder. Bu nedenle yosunları, kuzeyi gösteren pusulalar olarak kullanabilirsiniz.","Geceleyin yön bulmak çok kolaydır. Neden mi? Çünkü geceleri gökyüzünde kuzeyi gösteren Kutup Yıldızı görünür. Onu bulmak için Büyükayı takımyıldızını arayın. Bir kepçeye benzeyen biçimiyle bu takımyıldızını bulmanız hiç zor olmayacaktır.","Ay’ın hilal şekline sahip olduğu zamanlarda hilalin iki ucuna temas eden hayalî bir çizgi çekin. Çizgiyi çektiğinizde oluşan görüntü “b” harfini andırıyorsa hilalin uçları doğuyu, “d” harfini andırıyorsa batıyı gösteriyordur."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"- - - - Çünkü insan, emin olmadığı zaman arayış içinde olur. Yeni ipuçları ve detaylar fark eder, değişik duygu hâlleri yaşar. Yaptıklarından emin olanlar bu inceliklerden mahrum kalırlar. Bu nedenle insan, yaptığı her işe kuşkuyla yaklaşmalı.","stem":"Bu parçada boş bırakılan yere düşüncenin akışına göre aşağıdakilerden hangisi getirilmelidir?","options":["Sanatta ne aradığınız kadar nasıl aradığınız da değerlidir.","Kendinize güveniyorsanız başkalarının onayına ihtiyacınız olmaz.","Yaratıcılık -en azından işe başlarkenbelli bir öz güven gerektirir.","Yaptığınız işten eminseniz bir arayış içinde olmanıza gerek yoktur."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Mozart “- - - -” demişti. Bence bu oldukça bilgece bir cümle. Bir an coşkuyla dinlediğiniz müzik, başka bir anda yavaşlar ve bazen tamamen durur. Bir süreliğine size sessizliğin sesini dinletir. Sonra tekrar yükselir. Az önce yaşadığınız sessizlik anı şimdi dinlediğiniz melodiyi daha iyi duymanızı sağlar. Müzik denen büyü de burada gizlidir zaten.","stem":"Bu metinde boş bırakılan yere düşüncenin akışına göre aşağıdakilerden hangisi getirilmelidir?","options":["Müzik, notalarda değil aralardaki sessizliktedir.","Yalnızlık, müziğin bile seni dinlemesidir.","Kelimelerin başarısız olduğu yerde müzik konuşur.","Müzik, ruhu günlük hayatın tozlarından temizler."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Bitki resmi, bilimle sanatın kesişim noktalarından biridir. Amaç, biyolojik özellikleri incelenen bir bitkinin ölçeklendirilip ayırt edici nitelikleriyle resmedilmesidir. Kullanılan malzemeler ışığa, neme, zamanın yıpratıcı etkilerine dayanıklıdır. Botaniğin (bitki bilimi) yanı sıra ebru, tezhip, minyatür, çini gibi klasik Türk sanatlarında da bitki resimlerine yer verilir. Resim tamamlandıktan sonra yapan kişinin adı, resmin yapıldığı tarih ve bitkinin türünü belirten isim yazılır.","stem":"Bu metinden bitki resimleriyle ilgili aşağıdakilerin hangisine ulaşılamaz?","options":["Farklı sanat alanlarında kullanıldığına","Yapımında kullanılan araç-gerecin niteliğine","Alt köşesine bitkinin yerel isminin yazıldığına","Bilimle sanatın bütünleştiği bir uğraş olduğuna"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Nasrettin Hoca’ya tanımadığı biri yaklaşarak “Hoca’m, falanca köye kaç saatte gidebilirim?” diye sormuş. Hoca cevap vermemiş. Yabancı, “Herhâlde duymuyor!” diye düşünüp yoluna devam etmiş. Epey uzaklaştıktan sonra Hoca “Evlat, gel!” diye seslenmiş. Merakla yanına gelen adama “Sen üç saatte ancak gidersin.” demiş. Adam “Madem biliyordun, daha önce niye söylemedin?” deyince Hoca şöyle karşılık vermiş: “- - - -” Adam, Hoca’nın bu yaklaşımına şaşırarak yoluna devam etmiş.","stem":"Bu metinde boş bırakılan yere anlam akışına göre aşağıdakilerden hangisi getirilmelidir?","options":["Ne kadar bilirsen bil, söylediklerin karşındakinin anladığı kadardır.","Ne kadar süreceğini biliyordum ama senin nasıl bir tepki vereceğini görmek istedim.","Yolu biliyorum ama düşünmek için biraz zamana ihtiyaç duymuştum.","Yolun ne kadar süreceğini söylemem için senin yürüme hızını görmeliydim."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Karşısındakini zayıf düşürme gayreti içinde olmayan, ölçülü eleştiriye hepimizin ihtiyacı var. Bize eksiklerimizi hatırlatan, samimi bir şekilde hatalarımızı söyleyen insanları ciddiye almalıyız. Onları öteki hâline getirmek noksanlarımızı gidermez.","stem":"Bu parçada vurgulanmak istenen düşünce aşağıdakilerden hangisidir?","options":["Kişi eleştiriye kapalı olursa hatalarından kurtulamaz.","Eleştirinin ne olduğu kadar kimden geldiği de önemlidir.","Eleştiriye açık olmak, her söyleneni doğru kabul etmek anlamına gelmez.","Kişinin, hatalarının farkına varabilmesi için tarafsız bir göze ihtiyacı vardır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Meşe, dünyada 300’den fazla türü bulunan bir ağaç. Ömürleri ortalama 500 yıl. Bazı türlerinin boyları 30 metreye, enleri ise 2 metreye kadar ulaşabiliyor. Türkiye’de de bazıları endemik (yalnızca belli bir bölgede yetişen) olmak üzere 18 türü var. Meşe, Türkiye için oldukça değerli bir ağaç türü çünkü toprak yapısını ve iklimini sevdiği için ülkenin pek çok bölgesinde doğal olarak yetişebilmekte. Ayrıca uzun ömürlü olması ve köklerinin geniş bir alana yayılabilmesi nedeniyle erozyonla mücadele faaliyetlerinde sıklıkla tercih edilmekte.","stem":"Bu metinde meşe ağacı ile ilgili aşağıdakilerin hangisine değinilmemiştir?","options":["Uzun ömürlü olmasını sağlayan faktörlere","Erozyonla mücadelede kullanılma sebebine","Sadece ülkemizde yetişen türleri olduğuna","Türkiye’de niçin yaygın olduğuna"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Dede Korkut Hikâyeleri ile ilgili yüzlerce kaynak taranarak hazırlanan bu eserde, başta Türk dünyası olmak üzere dünyanın önde gelen araştırmacılarının görüşlerine yer verilmiştir. Eser, Dede Korkut Hikâyeleri’nin tarihî, efsanevi kişiliği Korkut Ata üzerine yazılmış edebî bir araştırma kitabıdır. Yazar, eserinde Korkut Ata’nın izini sürerken okuyucusunu da efsanevi kahramanlarla, tarihle, edebiyatla, müzikle dolu bir yolculuğa çıkarıyor.","stem":"Bu metinde sözü edilen eserle ilgili, I. Etkili bir üslubu olduğu II. Evrensel bir yönünün bulunduğu III. Kapsamlı bir çalışma sonucu hazırlandığı çıkarımlarından hangileri yapılabilir?","options":["Yalnız I","Yalnız III","I ve II","II ve III"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"“Balaklava” adı verilen şapka, soğuğu geçirmemesinden dolayı genellikle dağcılar tarafından kullanılır. Bu şapka türü, son yıllarda sentetik kumaşlardan üretiliyor ama ince yünden yapılmış olanları da var. Balaklava bazen tecrübesiz dağ sporcuları için zararlı olabiliyor, nedeni ise onu yürüyüşün başında kafalarına takmalarıdır. Bu durum vücudun hızla terlemesine yol açar. Balaklava çıkarılınca kişi doğrudan soğuğa maruz kalır. Bu yüzden balaklava, ihtiyaç duyulduğunda takılmalı; eğer terlenmişse sıcak bir ortama girilmeden asla çıkarılmamalıdır.","stem":"Bu metinde balaklava ile ilgili aşağıdakilerden hangisine değinilmemiştir?","options":["Başa takılma biçimine","Yapıldığı malzemenin özelliğine","Tercih edilme sebebine","Hangi durumda zararlı olabildiğine"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Davranışlarımıza çekidüzen verebilme yollarından biri başkalarının bizimle ilgili düşüncelerini öğrenmektir. Çünkü bizler davranışlarımızı net ve tarafsız olarak görmekte zorluk çeker; kendimize, başka insanların bizi gördüğü açılardan bakamayız. Keşke bakabilsek. Çehov’un sözü geliyor aklıma: “- - - - ”","stem":"Bu parçadaki boşluğa düşüncenin akışına göre aşağıdaki sözlerden hangisi getirilmelidir?","options":["Bir insana neye benzediğini gösterin, daha iyi bir insan olacaktır.","Bir haksızlık karşısında “Tarafsızım.” diyen biri, artık taraf olmuştur.","Yeni bir keşif için yeni yerler değil, yeni bir bakış açısı gerekir.","Her zaman doğruyu söylersen ne dediğini hatırlamak zorunda kalmazsın."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"1926’da İskoç mucit John Logie Baird bir insan yüzünü televizyonda görüntülemeyi ilk kez başardı. Aygıtını yaparken eski bir kutu, bir pasta kalıbı, örgü şişleri, bir bisiklet farı ve kartondan yapılmış bir disk kullandı. Elde ettiği ilk görüntü William Taynton adlı bir çocuğa aitti. Baird, aygıtını geliştirdikçe elde ettiği görüntüler daha belirgin hâle gelmeye başladı. Aynı yılın sonuna doğru televizyonuyla ilk kez halk önünde bir gösteri yaptı. Bu gösteriden sonra pek çok televizyon sistemi geliştirildi. 1936’da Londra’da siyah beyaz televizyon yayını yapılmaya başlandı.","stem":"Bu parçada ilk televizyonla ilgili aşağıdakilerden hangisine değinilmemiştir?","options":["Yapımında hangi malzemelerin kullanıldığına","Yansıttığı ilk görüntünün kime ait olduğuna","Ne zaman tanıtıldığına","Nerede icat edildiğine"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Diktiğim ilk ağaçtı ve bundan böyle her yıl - - - - bir tane fidan dikmeye karar verdim. Kim bilir, - - - - bir gün bir sürü ağacım - - - - bir ormanım olur.","stem":"Bu metinde boş bırakılan yerlere sırasıyla aşağıdakilerin hangisinde verilenler getirilmelidir?","options":["hatta – sanki – öyle ki","belki – sonra – en az","en az – belki – hatta","sadece – önce – sonra"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"(I) Bir akşamüstü, yerdeki yaprakları ayaklarımla savura savura ilerlediğime göre mevsim sonbahar olmalı. (II) Telaşla bir şeyler arıyoruz; daha doğrusu annem telaşlı, ben sadece gölge gibi yanında yürüyorum. (III) Gerçek dünyadan habersiz bütün çocuklar gibi kendi dünyama akıyorum. (IV) Tepedeki çalıların arasına, kaya diplerine tek tek bakıyor annem.","stem":"Bu parçada numaralanmış cümlelerle ilgili aşağıdaki belirlemelerden hangisi yanlıştır?","options":["I. cümlede olayın geçtiği zamanla ilgili bir çıkarımda bulunulmuştur.","II. cümlede olayın kahramanlarının durumuna ilişkin bilgi verilmiştir.","III. cümlede ana olayın ne olduğundan söz edilmiştir.","IV. cümlede olayın geçtiği mekânla ilgili ayrıntılara yer verilmiştir."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Aşağıda insanların kitap okumamak için öne sürdüğü mazeretlere çözüm önerileri verilmiştir. • Kitap okurken bir fincan çay ya da kahve içmeyi tercih edebilirsiniz. Bu tercih sizi uyanık tutacaktır. • Her nereye giderseniz gidin yanınızda bir kitap bulundurun ve yol boyunca eliniz ne zaman telefonunuza gitse onun yerine kitaba yönelin. Beklerken, metroda, ayaktayken hiç olmazsa bir iki satır okuyun. • Her gün için bir hedef koyun, birkaç dakika okumakla başlayın. Yavaş yavaş süreyi uzatın. Sonra zaten çok seveceksiniz ve bırakamayacaksınız.","stem":"Buna göre aşağıdakilerden hangisi çözüm önerileri verilen mazeretlerden biri değildir?","options":["Okumaya zaman bulamıyorum.","Nereden başlayacağımı bilemiyorum.","Kitap okumaya alışkın değilim.","Yorgun olduğum için okuyamıyorum."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Kırlangıçlar; her yıl ilkbahar aylarında Avrupa ve Asya kıtalarına, sonbaharda da Afrika kıtasına doğru göç eder. Günde ortalama 140 kilometre uçan kırlangıçlar, göç süresince yaklaşık 10 bin kilometrelik bir uçuşu tamamlamış olur. Kırlangıçlar, ilkbaharda 5-6 haftalık bir sürede göç ederken bu göç süresi sonbaharda artmaktadır.","stem":"Bu metinden “kırlangıçlar” ile ilgili aşağıdakilerin hangisine ulaşılabilir?","options":["Her yıl izledikleri göç yolları değişir.","Göç sırasında en çok yol alan kuş türüdür.","Göç ederken konakladıkları yerler aynıdır.","Sonbahardaki göç etme süreleri ilkbahardakinden uzundur."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Balık gebelikten itibaren anne adaylarına ve çocuklara tavsiye edilmektedir. Çocukların beyin gelişiminin hızlı olduğu anne karnındaki son iki üç ay ve 0-3 yaş dönemi için balığın önemi büyüktür. Çünkü balık eti, protein ve omega bakımından zengin olmakla birlikte iyot, selenyum, fosfor, magnezyum ve çinko mineralleri açısından da iyi bir besin kaynağıdır. Özellikle uskumru, lüfer, somon, hamsi gibi yağlı balıklar tavsiye edilir.","stem":"Bu metinde aşağıdaki sorulardan hangisinin cevabı yoktur?","options":["Ne sıklıkla balık tüketilmelidir?","Çocuklar neden balık yemelidir?","Önerilen balık türleri hangileridir?","Balığın besin değeri bakımından önemi nedir? a k ar. r. - n i-"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Üniversite okuyorsanız elbette bütün derslerin kendine göre zor yanları var. Üst düzey bir eğitim aldığınız için bu gerçeği kabul etmek zorundasınız. Bu yüzden derslerime kolay ya da zor diye yaklaşmak yerine anlamaya çalıştım. Ama yine de bir ders adı söylemem gerekirse matematik derdim.","stem":"Bu parça aşağıdaki sorulardan hangisine karşılık olarak söylenmiş olabilir?","options":["Üniversitede en zorlandığınız ders hangisiydi?","Üniversite okumak zor mudur?","Üniversitede başarılı olabilmek için ne yapmak gerekir?","Üniversite hayatınız nasıl geçmişti?"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Tiyatroda hata yapma şansınız yoktur. Çünkü olay canlı canlı izleyicilerin karşısında gerçekleşmektedir. Oysa sinemada bir sahnenin çekiminde hata yapıldığı zaman yeniden çekme imkanınız vardır. Tiyatro izleyici ile birkaç metrelik bir mesafede samimi bir ortamda gerçekleşirken sinemada bu samimiyet yoktur. Tiyatro evimizin bir odası gibidir tıpkı hayatımızın bir parçası olduğu gibi.","stem":"Yukarıdaki parça ile ilgili aşağıdakilerden hangisi söylenemez?","options":["Karşılaştırma yapılmıştır.","Örneklendirmeden yararlanılmıştır.","Açıklayıcı anlatım kullanılmıştır.","Düşünce yazısından alınmıştır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Konu bulma","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Neredeyse tüm kasları çalıştırması sebebiyle yüzme birçok uzman tarafından en faydalı spor olarak gösterilmektedir. Tüm kasların çalışması yüzme esnasında suya karşı uygulanan direnç ve kuvvet ile yakından ilgilidir. Yüzme metabolizmanın düzenli çalışması, kan dolaşımı ve dolaşım sistemi üzerinde çok olumlu etkiler meydana getirmektedir. Tabi tüm bu faydaları görebilmek için yüzülen suyun hijyen koşulları açısından uygun olması gerekmektedir.","stem":"Bu parçanı konusu aşağıdakilerden hangisidir?","options":["Yüzme sporunda temizliğin önemi","Yüzerken dikkat edilmesi gerekenler","Yüzme sporunun faydaları","Yüzme sporu ve kas gelişimi"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"},{"grade":6,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam ve yapı unsurlarını belirler.","text":"Alkol, sigara, uyuşturucu vb. bağımlılık yapan maddelerin pençesine çocuklarımızı kaptırmamak için en büyük sorumluluk anne babalara düşmektedir. Anne babalar çocuklarının kimlerle arkadaşlık yaptıklarını, nerelere gidip geldiklerini bilmek zorundadır. Evet iş hayatı yoğun, evi geçindirmek için çalışmak gerekir ama çocuklarımızı ihmal ettiğimiz zaman geçindirmemiz bir gereken bir ailemiz kalmayabilir. Bu yüzden çocuklarımızı asla ve asla ihmal etmeyelim.","stem":"Yukarıdaki parçada asıl anlatılmak istenen aşağıdakilerden hangisidir?","options":["Sigara sağlığa zararlı bir maddedir.","Anne babalar çocuklarının kötü alışkanlıklar kazanmaması için onlarla sürekli ilgilenmelidir.","Anne babalar evlerini geçindirmek için para kazanmak zorundadır.","İş hayatı çok yorucu olabilmektedir."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade6-expanded-paragraph"}];
